import tools.jackson.databind.ObjectMapper;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @ActiveProfiles("integration-test")
class GroupedSummaryConsistencyIT{
 static final TestDatabase DB=TestDatabase.create();static{Runtime.getRuntime().addShutdownHook(new Thread(DB::close));}
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){r.add("spring.datasource.url",DB::url);r.add("spring.datasource.username",DB::username);r.add("spring.datasource.password",DB::password);}
 @Autowired SummaryService summaries;@Autowired QaContextBuilder context;@Autowired UserRepository users;@Autowired ProfileService profiles;@Autowired FoodDatasetRepository datasets;@Autowired FoodReferenceRepository references;@Autowired FoodEntryPreviewService foodPreviews;@Autowired FoodEntryV2Service foods;@Autowired FoodEntryMutationService foodMutations;@Autowired FoodEntryReadService foodReads;@Autowired FoodSnapshotReader foodSnapshots;@Autowired ExerciseEntryV2Service exercises;@Autowired WorkoutEstimateService exercisePreviews;@Autowired WorkoutMutationService exerciseMutations;@Autowired WorkoutCorrectionPreviewService exerciseCorrections;@Autowired ExerciseEntryReadService exerciseReads;@Autowired WorkoutSnapshotReader exerciseSnapshots;@Autowired JdbcTemplate jdbc;@Autowired ObjectMapper json;
 User owner;WorkoutV2TestFixtures.Catalogue catalogue;final LocalDate day=LocalDate.of(2020,1,2);long dish,workout;
 @BeforeEach void setup(){owner=FoodV2TestFixtures.owner(users,profiles);catalogue=WorkoutV2TestFixtures.catalogue(jdbc);var a=FoodV2TestFixtures.reference(datasets,references,"1000");var b=FoodV2TestFixtures.reference(datasets,references,"400");var c=FoodV2TestFixtures.reference(datasets,references,"500");var ingredients=new ArrayList<FoodEntryInputs.Ingredient>();for(int i=0;i<4;i++)ingredients.add(new FoodEntryInputs.Ingredient(UUID.randomUUID(),(i<2?a:b).getId().toString(),new BigDecimal(i<2?"150":"75"),null,null));var entry=new FoodEntryInputs.Dish(UUID.randomUUID(),"Private synthetic recipe",MealType.LUNCH,"FULL_RECIPE",Map.of("kind","FRACTION","numerator",1,"denominator",3),ingredients,null);var input=new FoodEntryInputs.PreviewRequest(day,"Australia/Sydney",RecordSource.MANUAL,List.of(entry,new FoodEntryInputs.Single(UUID.randomUUID(),c.getId().toString(),new BigDecimal("100"),MealType.LUNCH,null,null)));var saved=foods.createBatchV2(owner.getId(),new FoodEntryInputs.BatchRequest(UUID.randomUUID(),day,input.zone(),input.source(),input.entries(),foodPreviews.previewNewBatch(owner.getId(),input).fingerprint()));dish=Long.parseLong(saved.roots().getFirst().id());workout=createExercise(false);}
 long createExercise(boolean unavailable){var strength=new ExerciseEntryInputs.PreviewPeriod(UUID.randomUUID(),"STRENGTH",Long.toString(catalogue.strengthOption()),new BigDecimal("50"),Map.of(),catalogue.movements().stream().map(id->new ExerciseEntryInputs.Movement(id.toString(),3L,8L,new BigDecimal("40"))).toList());var activity=new ExerciseEntryInputs.PreviewPeriod(UUID.randomUUID(),"ACTIVITY",Long.toString(unavailable?catalogue.unavailableOption():catalogue.cardioOption()),new BigDecimal("20"),Map.of(),List.of());ExerciseEntryInputs.PreviewEntry entry=unavailable?new ExerciseEntryInputs.QuickPreview(activity.clientEntryId(),activity):new ExerciseEntryInputs.WorkoutPreview(UUID.randomUUID(),"Private synthetic workout",List.of(strength,activity),null);var preview=exercisePreviews.previewNew(owner.getId(),new ExerciseEntryInputs.PreviewRequest(day,"Australia/Sydney",RecordSource.MANUAL,entry));var ps=entry instanceof ExerciseEntryInputs.QuickPreview q?List.of(q.period()):((ExerciseEntryInputs.WorkoutPreview)entry).periods();var confirmed=new ArrayList<ExerciseEntryInputs.Period>();for(int i=0;i<ps.size();i++){var p=ps.get(i);confirmed.add(new ExerciseEntryInputs.Period(p.clientEntryId(),p.periodKind(),p.optionId(),p.durationMinutes(),p.equipmentDetails(),p.movements(),preview.periods().get(i).calculationFingerprint()));}ExerciseEntryInputs.Entry reviewed=unavailable?new ExerciseEntryInputs.Quick(entry.clientEntryId(),confirmed.getFirst()):new ExerciseEntryInputs.Workout(entry.clientEntryId(),"Private synthetic workout",confirmed,null);return Long.parseLong(exercises.createEntryV2(owner.getId(),new ExerciseEntryInputs.CreateRequest(UUID.randomUUID(),day,"Australia/Sydney",RecordSource.MANUAL,preview.fingerprint(),reviewed)).roots().getFirst().id());}
 @Test void rootAndLeafCountsRemainDistinctAcrossAllViewsAndAllowedQaFacts(){var daily=summaries.daily(owner.getId(),day,"Australia/Sydney").day();assertEquals(5,daily.foodCount());assertEquals(2,daily.foodEntryCount());assertEquals(2,daily.exerciseCount());assertEquals(1,daily.exerciseEntryCount());assertEquals(new BigDecimal("1700.000"),daily.intake().knownSum());assertEquals(new BigDecimal("1342.366"),daily.expenditure().knownSum());assertEquals(new BigDecimal("70.00"),daily.activityMinutes());assertEquals(5,daily.intake().recordCount());assertEquals(2,daily.expenditure().recordCount());assertEquals(daily.intake().knownSum(),jdbc.queryForObject("SELECT sum(energy_kj) FROM food_record WHERE user_id=? AND deleted_at IS NULL",BigDecimal.class,owner.getId()));assertEquals(daily.expenditure().knownSum(),jdbc.queryForObject("SELECT sum(estimated_kj) FROM exercise_record WHERE user_id=? AND deleted_at IS NULL",BigDecimal.class,owner.getId()));assertEquals(2,foodReads.listRoots(owner.getId(),day,day,null,"Australia/Sydney",0,20).totalMatches());assertEquals(4,foodSnapshots.detailForReuse(owner.getId(),"dish",dish).componentCount());assertEquals(1,exerciseReads.listRoots(owner.getId(),day,day,"Australia/Sydney",0,20).totalMatches());var period=summaries.period(owner.getId(),day,day,"Australia/Sydney");assertEquals(period,summaries.trends(owner.getId(),day,day,null,"Australia/Sydney"));assertEquals(period.days().getFirst(),daily);assertEquals(2,period.totals().foodEntryCount());assertEquals(1,period.totals().exerciseEntryCount());var weekly=summaries.weekly(owner.getId(),day.plusDays(6),"Australia/Sydney").current();assertEquals(daily.intake(),weekly.totals().intake());assertEquals(daily.expenditure(),weekly.totals().expenditure());var qa=context.buildAllowedFacts(owner.getId(),new QaRequest.RecordRange(day,day),"Australia/Sydney");assertEquals(5,qa.totals().foodCount());assertEquals(2,qa.totals().foodEntryCount());assertEquals(1,qa.totals().exerciseEntryCount());assertEquals(new BigDecimal("1700.000"),qa.totals().intakeKj().knownTotal());String external=json.writeValueAsString(qa);for(var secret:List.of("Private synthetic","clientEntryId","referenceId","metUsed","loadKg","weightKg"))assertFalse(external.contains(secret));assertNull(period.goalComparison());}
 @Test void proportionCorrectionDateMoveAndWholeDeletionConserveCountsAndEnergy(){var old=json.convertValue(foodSnapshots.detailForReuse(owner.getId(),"dish",dish).input(),FoodEntryInputs.Dish.class);var changed=new FoodEntryInputs.Dish(old.clientEntryId(),old.name(),old.mealType(),old.inputMode(),Map.of("kind","FRACTION","numerator",1,"denominator",2),old.ingredients(),null);LocalDate next=day.plusDays(1);var preview=foodPreviews.previewOwnedRoot(owner.getId(),"dish",dish,new FoodEntryInputs.CorrectionRequest(0L,next,"Australia/Sydney",changed));foodMutations.updateOwnedRoot(owner.getId(),"dish",dish,new FoodEntryInputs.UpdateRequest(0L,next,"Australia/Sydney",changed,preview.fingerprint()));var exercise=exerciseSnapshots.detailForReuse(owner.getId(),"workout",workout);var review=exerciseCorrections.previewOwnedRoot(owner.getId(),"workout",workout,new ExerciseEntryInputs.CorrectionRequest(0L,next,"Australia/Sydney",exercise.input()));exerciseMutations.updateOwnedRoot(owner.getId(),"workout",workout,new ExerciseEntryInputs.UpdateRequest(0L,next,"Australia/Sydney",exercise.input(),review.fingerprint()));var oldDay=summaries.daily(owner.getId(),day,"Australia/Sydney").day();assertEquals(new BigDecimal("500.000"),oldDay.intake().knownSum());assertEquals(1,oldDay.foodCount());assertEquals(1,oldDay.foodEntryCount());assertEquals(0,oldDay.exerciseEntryCount());var moved=summaries.daily(owner.getId(),next,"Australia/Sydney").day();assertEquals(new BigDecimal("1800.000"),moved.intake().knownSum());assertEquals(4,moved.foodCount());assertEquals(1,moved.foodEntryCount());assertEquals(1,moved.exerciseEntryCount());var period=summaries.period(owner.getId(),day,next,"Australia/Sydney");assertEquals(new BigDecimal("2300.000"),period.totals().intake().knownSum());assertEquals(5,period.totals().foodCount());assertEquals(2,period.totals().foodEntryCount());assertEquals(new BigDecimal("70.00"),period.totals().activityMinutes());foodMutations.softDeleteOwnedRoot(owner.getId(),"dish",dish,1L);exerciseMutations.softDeleteOwnedRoot(owner.getId(),"workout",workout,1L);var after=summaries.period(owner.getId(),day,next,"Australia/Sydney");assertEquals(new BigDecimal("500.000"),after.totals().intake().knownSum());assertEquals(1,after.totals().foodCount());assertEquals(1,after.totals().foodEntryCount());assertEquals(0,after.totals().exerciseCount());assertEquals(0,after.totals().exerciseEntryCount());assertNull(after.totals().expenditure().knownSum());assertNull(after.totals().activityMinutes());}
 @Test void unavailablePeriodRetainsFullMinutesAndMissingSemantics(){createExercise(true);var partial=summaries.daily(owner.getId(),day,"Australia/Sydney").day();assertEquals(3,partial.exerciseCount());assertEquals(2,partial.exerciseEntryCount());assertEquals(1,partial.expenditure().missingValueCount());assertTrue(partial.expenditure().partial());assertEquals(new BigDecimal("90.00"),partial.activityMinutes());assertEquals(new BigDecimal("1342.366"),partial.expenditure().knownSum());exerciseMutations.softDeleteOwnedRoot(owner.getId(),"workout",workout,0L);var missing=summaries.daily(owner.getId(),day,"Australia/Sydney").day();assertEquals(1,missing.exerciseCount());assertEquals(1,missing.exerciseEntryCount());assertEquals(new BigDecimal("20.00"),missing.activityMinutes());assertTrue(missing.expenditure().hasData());assertFalse(missing.expenditure().partial());assertNull(missing.expenditure().knownSum());var qa=context.buildAllowedFacts(owner.getId(),new QaRequest.RecordRange(day,day),"Australia/Sydney");assertNull(qa.totals().expenditureKj().knownTotal());assertEquals(1,qa.totals().expenditureKj().missingValueCount());}
}
